CREATE OR REPLACE FUNCTION public.admin_cancel_scheduled_announcement(pin_input text, announcement_id_input uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare affected integer;
begin
 if not coalesce(public.verify_admin_pin(pin_input),false) then raise exception 'PIN de administrador incorrecto'; end if;
 update public.chat_scheduled_announcements set status='cancelled' where id=announcement_id_input and status='pending';
 get diagnostics affected = row_count;
 return affected=1;
end $function$

CREATE OR REPLACE FUNCTION public.admin_close_room_poll(pin_input text, poll_id_input uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n integer;
begin
 if not coalesce(public.verify_admin_pin(pin_input),false) then raise exception 'PIN de administrador incorrecto'; end if;
 update public.chat_room_polls set is_closed=true,updated_at=now() where id=poll_id_input and not is_closed;
 get diagnostics n=row_count; return n=1;
end $function$

CREATE OR REPLACE FUNCTION public.admin_create_room(pin_input text, room_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    new_room_id BIGINT;
    clean_name TEXT;
BEGIN
    -- Verificar PIN del administrador
    IF NOT public.verify_admin_pin(pin_input) THEN
        RAISE EXCEPTION 'PIN incorrecto';
    END IF;

    clean_name := trim(room_name);

    IF clean_name IS NULL OR clean_name = '' THEN
        RAISE EXCEPTION 'El nombre de la sala no puede estar vacío';
    END IF;

    INSERT INTO public.rooms (name)
    VALUES (clean_name)
    RETURNING id INTO new_room_id;

    RETURN jsonb_build_object(
        'success', true,
        'id', new_room_id,
        'name', clean_name
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_room_poll(pin_input text, room_id_input bigint, question_input text, options_input jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare new_id uuid; clean_options jsonb;
begin
 if not coalesce(public.verify_admin_pin(pin_input),false) then raise exception 'PIN de administrador incorrecto'; end if;
 if not exists(select 1 from public.rooms where id=room_id_input) then raise exception 'La sala no existe'; end if;
 if question_input is null or char_length(btrim(question_input)) not between 3 and 180 then raise exception 'La pregunta debe tener entre 3 y 180 caracteres'; end if;
 if options_input is null or jsonb_typeof(options_input) is distinct from 'array' or jsonb_array_length(options_input) not between 2 and 6 then raise exception 'La encuesta debe tener entre 2 y 6 opciones'; end if;
 select jsonb_agg(to_jsonb(v)) into clean_options from (select btrim(value) as v from jsonb_array_elements_text(options_input)) q where char_length(v) between 1 and 80;
 if clean_options is null or jsonb_array_length(clean_options)<>jsonb_array_length(options_input) then raise exception 'Cada opción debe tener entre 1 y 80 caracteres'; end if;
 if (select count(distinct lower(value)) from jsonb_array_elements_text(clean_options))<>jsonb_array_length(clean_options) then raise exception 'No puede haber opciones repetidas'; end if;
 insert into public.chat_room_polls(room_id,question,options,created_by) values(room_id_input,btrim(question_input),clean_options,auth.uid()) returning id into new_id;
 return new_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_delete_room(pin_input text, room_id_input bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN

    IF NOT public.verify_admin_pin(pin_input) THEN
        RAISE EXCEPTION 'PIN de administrador incorrecto';
    END IF;

    DELETE FROM public.rooms
    WHERE id = room_id_input;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;

END;
$function$

CREATE OR REPLACE FUNCTION public.admin_moderate_user(action_name text, pin_input text, room_id_input bigint, target_sender_id text, reason_input text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_nickname text;
  expiry timestamptz;
  selected_action text;
  target_ip inet;
  moderation_reason text;
BEGIN
  IF NOT public.verify_admin_pin(pin_input) THEN
    RAISE EXCEPTION 'PIN incorrecto';
  END IF;

  IF public.is_wichat_admin(target_sender_id) THEN
    RAISE EXCEPTION 'No se puede expulsar ni banear a un administrador';
  END IF;

  IF target_sender_id IS NULL OR trim(target_sender_id) = '' THEN
    RAISE EXCEPTION 'Usuario no válido';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.rooms WHERE id = room_id_input) THEN
    RAISE EXCEPTION 'La sala no existe';
  END IF;

  selected_action := lower(action_name);
  IF selected_action NOT IN ('kick', 'ban') THEN
    RAISE EXCEPTION 'Acción no válida';
  END IF;

  moderation_reason := nullif(left(trim(coalesce(reason_input, '')), 500), '');
  IF moderation_reason IS NULL THEN
    RAISE EXCEPTION 'Tenés que indicar el motivo de la moderación';
  END IF;

  SELECT nickname INTO target_nickname
  FROM public.messages
  WHERE sender_id = target_sender_id AND room_id = room_id_input
  ORDER BY created_at DESC
  LIMIT 1;
  target_nickname := COALESCE(target_nickname, 'Usuario');
  expiry := now() + interval '5 minutes';

  IF selected_action = 'kick' THEN
    DELETE FROM public.wichat_kicks
    WHERE sender_id = target_sender_id AND room_id = room_id_input;

    INSERT INTO public.wichat_room_bans
      (sender_id, room_id, nickname, reason, created_at, expires_at)
    VALUES
      (target_sender_id, room_id_input, target_nickname, moderation_reason, now(), expiry)
    ON CONFLICT (sender_id, room_id) DO UPDATE SET
      nickname = EXCLUDED.nickname,
      reason = EXCLUDED.reason,
      created_at = now(),
      expires_at = EXCLUDED.expires_at;
  ELSE
    SELECT client_ip INTO target_ip
    FROM public.wichat_user_ips
    WHERE sender_id = target_sender_id;

    DELETE FROM public.wichat_kicks WHERE sender_id = target_sender_id;
    DELETE FROM public.wichat_room_bans WHERE sender_id = target_sender_id;
    DELETE FROM public.wichat_bans WHERE sender_id = target_sender_id;

    INSERT INTO public.wichat_bans
      (sender_id, room_id, nickname, reason, created_at, expires_at)
    VALUES
      (target_sender_id, room_id_input, target_nickname, moderation_reason, now(), expiry);

    IF target_ip IS NOT NULL THEN
      INSERT INTO public.wichat_ip_bans
        (client_ip, room_id, nickname, reason, expires_at)
      VALUES
        (target_ip, room_id_input, target_nickname, moderation_reason, expiry)
      ON CONFLICT (client_ip, room_id) DO UPDATE SET
        nickname = EXCLUDED.nickname,
        reason = EXCLUDED.reason,
        created_at = now(),
        expires_at = EXCLUDED.expires_at;
    END IF;
  END IF;

  INSERT INTO public.wichat_moderation_events
    (sender_id, room_id, action, reason)
  VALUES
    (target_sender_id, room_id_input, selected_action, moderation_reason);

  RETURN jsonb_build_object(
    'success', true,
    'action', selected_action,
    'ip_banned', CASE WHEN selected_action = 'ban' THEN target_ip IS NOT NULL ELSE false END,
    'expires_at', expiry,
    'reason', moderation_reason,
    'message', CASE
      WHEN selected_action = 'ban' THEN 'Estás baneado por cinco minutos'
      ELSE 'Has sido expulsado por cinco minutos'
    END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_moderate_user(pin_input text, target_sender_id text, room_id_input bigint, action_name text, reason_input text, duration_minutes_input integer, moderator_id_input uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_nickname text;
  expiry timestamptz;
  selected_action text;
  target_ip inet;
  moderation_reason text;
  prior_sanctions integer;
  applied_minutes integer;
begin
  if not public.verify_admin_pin(pin_input) then
    raise exception 'PIN incorrecto';
  end if;
  if target_sender_id is null or trim(target_sender_id) = '' then
    raise exception 'Usuario no válido';
  end if;
  if public.is_wichat_admin(target_sender_id) then
    raise exception 'No se puede expulsar ni banear a un administrador';
  end if;
  if not exists(select 1 from public.rooms where id=room_id_input) then
    raise exception 'La sala no existe';
  end if;

  selected_action := lower(action_name);
  if selected_action not in ('kick','ban') then
    raise exception 'Acción no válida';
  end if;
  if duration_minutes_input not in (5,15,60,1440) then
    raise exception 'Duración no válida';
  end if;
  moderation_reason := nullif(left(trim(coalesce(reason_input,'')),500),'');
  if moderation_reason is null then
    raise exception 'Tenés que indicar el motivo de la moderación';
  end if;

  select nickname into target_nickname
  from public.messages
  where sender_id=target_sender_id and room_id=room_id_input
  order by created_at desc limit 1;
  target_nickname := coalesce(target_nickname,'Usuario');

  select count(*)::integer into prior_sanctions
  from public.wichat_moderation_events
  where sender_id=target_sender_id
    and created_at >= now()-interval '30 days'
    and action in ('kick','ban');

  applied_minutes := greatest(
    duration_minutes_input,
    case
      when prior_sanctions >= 3 then 1440
      when prior_sanctions = 2 then 60
      when prior_sanctions = 1 then 15
      else 5
    end
  );
  expiry := now() + make_interval(mins => applied_minutes);

  if selected_action='kick' then
    delete from public.wichat_kicks
      where sender_id=target_sender_id and room_id=room_id_input;
    insert into public.wichat_room_bans
      (sender_id,room_id,nickname,reason,created_at,expires_at)
    values
      (target_sender_id,room_id_input,target_nickname,moderation_reason,now(),expiry)
    on conflict (sender_id,room_id) do update set
      nickname=excluded.nickname, reason=excluded.reason,
      created_at=now(), expires_at=excluded.expires_at;
  else
    select client_ip into target_ip
    from public.wichat_user_ips where sender_id=target_sender_id;

    delete from public.wichat_kicks where sender_id=target_sender_id;
    delete from public.wichat_room_bans where sender_id=target_sender_id;
    delete from public.wichat_bans where sender_id=target_sender_id;

    insert into public.wichat_bans
      (sender_id,room_id,nickname,reason,created_at,expires_at)
    values
      (target_sender_id,room_id_input,target_nickname,moderation_reason,now(),expiry);

    if target_ip is not null then
      insert into public.wichat_ip_bans
        (client_ip,room_id,nickname,reason,expires_at)
      values
        (target_ip,room_id_input,target_nickname,moderation_reason,expiry)
      on conflict (client_ip,room_id) do update set
        nickname=excluded.nickname,reason=excluded.reason,
        created_at=now(),expires_at=excluded.expires_at;
    end if;
  end if;

  insert into public.wichat_moderation_events
    (sender_id,room_id,action,reason,duration_minutes,moderated_by)
  values
    (target_sender_id,room_id_input,selected_action,moderation_reason,applied_minutes,moderator_id_input);

  return jsonb_build_object(
    'success',true,'action',selected_action,'duration_minutes',applied_minutes,
    'prior_sanctions',prior_sanctions,'expires_at',expiry,
    'ip_banned',case when selected_action='ban' then target_ip is not null else false end,
    'reason',moderation_reason
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_schedule_announcement(pin_input text, room_id_input bigint, message_input text, scheduled_at_input timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare new_id uuid;
begin
 if not coalesce(public.verify_admin_pin(pin_input),false) then raise exception 'PIN de administrador incorrecto'; end if;
 if not exists(select 1 from public.rooms where id=room_id_input) then raise exception 'La sala no existe'; end if;
 if message_input is null or char_length(btrim(message_input)) not between 1 and 500 then raise exception 'El mensaje debe tener entre 1 y 500 caracteres'; end if;
 if scheduled_at_input is null or scheduled_at_input <= now() or scheduled_at_input > now()+interval '90 days' then raise exception 'Elegí una fecha futura dentro de los próximos 90 días'; end if;
 insert into public.chat_scheduled_announcements(room_id,message,scheduled_at,created_by) values(room_id_input,btrim(message_input),scheduled_at_input,auth.uid()) returning id into new_id;
 return new_id;
end $function$

CREATE OR REPLACE FUNCTION public.admin_set_room_topic(pin_input text, room_id_input bigint, topic_input text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Verificar el PIN del administrador
  if not coalesce(public.verify_admin_pin(pin_input), false) then
    raise exception 'PIN de administrador incorrecto';
  end if;

  if room_id_input is null then
    raise exception 'No se indicó una sala';
  end if;

  -- Si el tópico está vacío, borrarlo
  if topic_input is null or btrim(topic_input) = '' then
    delete from public.chat_room_topics
    where room_id = room_id_input;
  else
    if char_length(btrim(topic_input)) > 180 then
      raise exception 'El tópico no puede superar los 180 caracteres';
    end if;

    insert into public.chat_room_topics (room_id, topic)
    values (room_id_input, btrim(topic_input))
    on conflict (room_id)
    do update set
      topic = excluded.topic,
      updated_at = now();
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_set_room_vip(pin_input text, room_id_input bigint, vip_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pin_ok boolean;
begin
 select public.verify_admin_pin(pin_input) into pin_ok;
 if coalesce(pin_ok,false) is not true then raise exception 'PIN de administrador incorrecto'; end if;
 update public.rooms set is_vip=vip_enabled where id=room_id_input;
 return found;
end;$function$

CREATE OR REPLACE FUNCTION public.admin_set_room_welcome(pin_input text, room_id_input bigint, message_input text, enabled_input boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
 if public.verify_admin_pin(pin_input) is distinct from true then raise exception 'PIN incorrecto'; end if;
 if not exists(select 1 from public.rooms where id=room_id_input) then raise exception 'La sala no existe'; end if;
 if message_input is null or char_length(btrim(message_input))=0 then
   delete from public.chat_room_welcome_messages where room_id=room_id_input;
   return true;
 end if;
 if char_length(btrim(message_input))>300 then raise exception 'El mensaje no puede superar 300 caracteres'; end if;
 insert into public.chat_room_welcome_messages(room_id,message,enabled,updated_at)
 values(room_id_input,btrim(message_input),coalesce(enabled_input,true),now())
 on conflict(room_id) do update set message=excluded.message,enabled=excluded.enabled,updated_at=now();
 return true;
end; $function$

CREATE OR REPLACE FUNCTION public.admin_set_vip_member(pin_input text, nickname_input text, vip_enabled boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pin_ok boolean; target_user uuid; matches integer;
begin
 select public.verify_admin_pin(pin_input) into pin_ok;
 if coalesce(pin_ok,false) is not true then raise exception 'PIN de administrador incorrecto'; end if;
 if nickname_input is null or length(trim(nickname_input))<1 or length(trim(nickname_input))>24 then raise exception 'Nick no válido'; end if;
 select count(*),min(user_id::text)::uuid into matches,target_user from public.chat_profiles where lower(nickname)=lower(trim(nickname_input));
 if matches=0 then raise exception 'No se encontró ese usuario'; end if;
 if matches>1 then raise exception 'Hay más de un usuario con ese nick; no se modificó ninguna membresía'; end if;
 if vip_enabled then
  insert into public.chat_vip_members(user_id,granted_by,note) values(target_user,'UNIX','Membresía otorgada desde el panel') on conflict(user_id) do nothing;
 else delete from public.chat_vip_members where user_id=target_user;
 end if;
 return true;
end;$function$

CREATE OR REPLACE FUNCTION public.admin_unban_user(pin_input text, target_sender_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    target_ip inet;
    deleted_count integer := 0;
    affected integer;
BEGIN
    IF NOT public.verify_admin_pin(pin_input) THEN
        RAISE EXCEPTION 'PIN incorrecto';
    END IF;

    IF target_sender_id IS NULL OR trim(target_sender_id) = '' THEN
        RAISE EXCEPTION 'Usuario no válido';
    END IF;

    SELECT client_ip
    INTO target_ip
    FROM public.wichat_user_ips
    WHERE sender_id = target_sender_id;

    DELETE FROM public.wichat_bans
    WHERE sender_id = target_sender_id;

    GET DIAGNOSTICS affected = ROW_COUNT;
    deleted_count := deleted_count + affected;

    DELETE FROM public.wichat_room_bans
    WHERE sender_id = target_sender_id;

    GET DIAGNOSTICS affected = ROW_COUNT;
    deleted_count := deleted_count + affected;

    DELETE FROM public.wichat_kicks
    WHERE sender_id = target_sender_id;

    GET DIAGNOSTICS affected = ROW_COUNT;
    deleted_count := deleted_count + affected;

    IF target_ip IS NOT NULL THEN
        DELETE FROM public.wichat_ip_bans
        WHERE client_ip = target_ip;

        GET DIAGNOSTICS affected = ROW_COUNT;
        deleted_count := deleted_count + affected;
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'deleted', deleted_count,
        'message', 'Usuario desbloqueado correctamente'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_chat_access(sender_id_input text, room_id_input bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 headers json;
 ip_text text;
 user_ip inet;
 sender_uuid uuid;
begin
 headers:=coalesce(nullif(current_setting('request.headers',true),'')::json,'{}'::json);
 ip_text:=nullif(trim(headers->>'cf-connecting-ip'),'');
 if ip_text is null then ip_text:=nullif(trim(split_part(coalesce(headers->>'x-forwarded-for',''),',',1)),''); end if;
 if ip_text is not null then
  begin user_ip:=ip_text::inet; exception when others then user_ip:=null; end;
 end if;
 if user_ip is not null then
  insert into public.wichat_user_ips(sender_id,client_ip,updated_at)
  values(sender_id_input,user_ip,now())
  on conflict(sender_id) do update set client_ip=excluded.client_ip,updated_at=now();
 else
  select client_ip into user_ip from public.wichat_user_ips where sender_id=sender_id_input;
 end if;
 if exists(select 1 from public.wichat_bans where sender_id=sender_id_input and (expires_at is null or expires_at>now())) then return false; end if;
 if exists(select 1 from public.wichat_room_bans where sender_id=sender_id_input and room_id=room_id_input and expires_at>now()) then return false; end if;
 if user_ip is not null and exists(select 1 from public.wichat_ip_bans where client_ip=user_ip and room_id=room_id_input and expires_at>now()) then return false; end if;
 if exists(select 1 from public.rooms where id=room_id_input and is_vip=true) then
  if auth.uid() is null or sender_id_input is distinct from auth.uid()::text then return false; end if;
  sender_uuid:=auth.uid();
  if not exists(select 1 from public.chat_vip_members where user_id=sender_uuid) then return false; end if;
 end if;
 return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_chat_nickname(nickname_input text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    uid TEXT;
    nick TEXT;
    nick_key TEXT;
    affected INTEGER;
BEGIN
    uid := auth.uid()::TEXT;
    nick := trim(nickname_input);

    IF uid IS NULL OR length(nick) < 2 OR length(nick) > 25 THEN
        RETURN FALSE;
    END IF;

    nick_key := lower(
        translate(
            nick,
            'ÁÉÍÓÚÜÑáéíóúüñ',
            'AEIOUUNaeiouun'
        )
    );

    DELETE FROM public.wichat_active_nicks
    WHERE expires_at < now();

    -- Renovar la reserva del mismo usuario
    UPDATE public.wichat_active_nicks
    SET nickname = nick,
        nickname_key = nick_key,
        expires_at = now() + interval '2 minutes'
    WHERE sender_id = uid;

    GET DIAGNOSTICS affected = ROW_COUNT;

    IF affected > 0 THEN
        RETURN TRUE;
    END IF;

    -- Crear una reserva nueva
    INSERT INTO public.wichat_active_nicks
        (nickname_key, nickname, sender_id, expires_at)
    VALUES
        (nick_key, nick, uid, now() + interval '2 minutes')
    ON CONFLICT DO NOTHING;

    GET DIAGNOSTICS affected = ROW_COUNT;

    RETURN affected > 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.heartbeat_chat_nickname()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    affected INTEGER;
BEGIN
    UPDATE public.wichat_active_nicks
    SET expires_at = now() + interval '2 minutes'
    WHERE sender_id = auth.uid()::TEXT;

    GET DIAGNOSTICS affected = ROW_COUNT;

    RETURN affected > 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.process_chat_scheduled_announcements()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare item record; sent_count integer := 0;
begin
 for item in select id,room_id,message from public.chat_scheduled_announcements where status='pending' and scheduled_at<=now() order by scheduled_at for update skip locked
 loop
  insert into public.messages(nickname,message,content,room_id,sender_id,message_type) values('UNIX',item.message,item.message,item.room_id,null,'text');
  update public.chat_scheduled_announcements set status='sent',sent_at=now() where id=item.id and status='pending';
  if found then sent_count:=sent_count+1; end if;
 end loop;
 return sent_count;
end $function$

CREATE OR REPLACE FUNCTION public.release_chat_nickname()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    affected INTEGER;
BEGIN
    DELETE FROM public.wichat_active_nicks
    WHERE sender_id = auth.uid()::TEXT;

    GET DIAGNOSTICS affected = ROW_COUNT;

    RETURN affected > 0;
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_admin_pin(pin_input text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    crypto_schema text;
    saved_hash text;
    valid_pin boolean;
BEGIN
    SELECT n.nspname
    INTO crypto_schema
    FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'pgcrypto';

    SELECT pin_hash
    INTO saved_hash
    FROM public.wichat_admin_config
    WHERE singleton = true;

    IF saved_hash IS NULL OR crypto_schema IS NULL THEN
        RETURN false;
    END IF;

    EXECUTE format(
        'SELECT %I.crypt($1, $2) = $2',
        crypto_schema
    )
    INTO valid_pin
    USING pin_input, saved_hash;

    RETURN COALESCE(valid_pin, false);
END;
$function$

CREATE OR REPLACE FUNCTION public.vote_chat_room_poll(poll_id_input uuid, option_index_input integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare p public.chat_room_polls%rowtype;
begin
 if auth.uid() is null then raise exception 'Tenés que iniciar sesión para votar'; end if;
 select * into p from public.chat_room_polls where id=poll_id_input for update;
 if not found then raise exception 'La encuesta no existe'; end if;
 if p.is_closed then raise exception 'La encuesta está cerrada'; end if;
 if option_index_input<0 or option_index_input>=jsonb_array_length(p.options) then raise exception 'Opción inválida'; end if;
 insert into public.chat_room_poll_votes(poll_id,user_id,option_index) values(poll_id_input,auth.uid(),option_index_input);
 update public.chat_room_polls set updated_at=now() where id=poll_id_input;
 return true;
exception when unique_violation then raise exception 'Ya votaste en esta encuesta';
end $function$

CREATE OR REPLACE FUNCTION public.wichat_acquire_nickname(p_nickname text, p_sender_id text, p_admin_pin text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nick text := btrim(coalesce(p_nickname,''));
  v_norm text;
BEGIN
  IF auth.uid() IS NULL OR auth.uid()::text <> p_sender_id THEN
    RAISE EXCEPTION 'Sesión no válida.';
  END IF;

  IF length(v_nick) < 1 OR length(v_nick) > 25 THEN
    RAISE EXCEPTION 'El Nick debe tener entre 1 y 25 caracteres.';
  END IF;

  v_norm := lower(v_nick);

  IF v_norm = 'unix'
     AND NOT coalesce(public.verify_admin_pin(coalesce(p_admin_pin,'')),false) THEN
    RAISE EXCEPTION 'El Nick UNIX está reservado para el administrador.';
  END IF;

  -- Serializa intentos simultáneos para el mismo Nick, incluso desde dispositivos distintos.
  PERFORM pg_advisory_xact_lock(hashtext(v_norm));

  DELETE FROM public.wichat_nicknames
  WHERE expires_at <= now();

  -- No permitir que un invitado suplante un Nick que pertenece a una cuenta registrada.
  IF EXISTS (
    SELECT 1
    FROM public.chat_profiles cp
    WHERE cp.is_registered = true
      AND lower(btrim(cp.nickname)) = v_norm
      AND cp.user_id::text <> p_sender_id
  ) THEN
    RETURN false;
  END IF;

  -- Si otro usuario/dispositivo ya tiene el Nick activo, rechazar el ingreso.
  IF EXISTS (
    SELECT 1
    FROM public.wichat_nicknames wn
    WHERE wn.nickname_norm = v_norm
      AND wn.sender_id <> p_sender_id
      AND wn.expires_at > now()
  ) THEN
    RETURN false;
  END IF;

  INSERT INTO public.wichat_nicknames(sender_id,nickname,nickname_norm,expires_at)
  VALUES(p_sender_id,v_nick,v_norm,now()+interval '2 minutes')
  ON CONFLICT(sender_id) DO UPDATE
    SET nickname=EXCLUDED.nickname,
        nickname_norm=EXCLUDED.nickname_norm,
        expires_at=EXCLUDED.expires_at;

  RETURN true;
EXCEPTION
  WHEN unique_violation THEN
    RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.wichat_antispam_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
 v_sender text; v_body text; v_media text; v_hash text; v_context text;
 v_now timestamptz:=clock_timestamp(); v_recent_count integer;
 v_last_sent timestamptz; v_duplicate_count integer;
begin
 if coalesce(current_setting('request.jwt.claim.role',true),'')='service_role' then return new; end if;
 v_sender:=to_jsonb(new)->>'sender_id';
 if v_sender is null or btrim(v_sender)='' then return new; end if;
 v_body:=coalesce(to_jsonb(new)->>'message',to_jsonb(new)->>'content','');
 v_media:=coalesce(to_jsonb(new)->>'media_url','');
 v_context:=coalesce(to_jsonb(new)->>'room_id',to_jsonb(new)->>'recipient_id','chat');
 v_body:=lower(regexp_replace(btrim(v_body),'\s+',' ','g'));
 if v_body='' then v_body:='media:'||v_media; end if;
 v_hash:=md5(v_body);
 perform pg_advisory_xact_lock(hashtextextended(v_sender,0));
 select count(*),max(sent_at) into v_recent_count,v_last_sent
 from public.chat_antispam_events where sender_id=v_sender and sent_at>v_now-interval '10 seconds';
 if v_recent_count>=6 then raise exception 'Estás enviando mensajes demasiado rápido. Esperá unos segundos.' using errcode='P0001'; end if;
 if v_last_sent is not null and v_now-v_last_sent<interval '1200 milliseconds' then
  raise exception 'Esperá un momento antes de enviar otro mensaje.' using errcode='P0001';
 end if;
 select count(*) into v_duplicate_count from public.chat_antispam_events
 where sender_id=v_sender and body_hash=v_hash and sent_at>v_now-interval '60 seconds';
 if v_duplicate_count>=2 then
  raise exception 'Detectamos mensajes repetidos. Cambiá el texto antes de volver a enviarlo.' using errcode='P0001';
 end if;
 insert into public.chat_antispam_events(sender_id,body_hash,context_key,sent_at)
 values(v_sender,v_hash,v_context,v_now);
 if mod(extract(epoch from v_now)::bigint,100)=0 then
  delete from public.chat_antispam_events where sent_at<v_now-interval '1 day';
 end if;
 return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.wichat_apply_ip_ban()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_ip inet;
  target_nickname text;
  moderation_reason text;
BEGIN
  IF NEW.action <> 'ban' THEN
    RETURN NEW;
  END IF;

  SELECT client_ip INTO target_ip
  FROM public.wichat_user_ips
  WHERE sender_id = NEW.sender_id;

  IF target_ip IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT nickname INTO target_nickname
  FROM public.wichat_bans
  WHERE sender_id = NEW.sender_id
  ORDER BY created_at DESC
  LIMIT 1;

  moderation_reason := COALESCE(
    NULLIF(trim(NEW.reason), ''),
    'Baneo por administrador'
  );

  INSERT INTO public.wichat_ip_bans (
    client_ip, room_id, nickname, reason, expires_at
  )
  VALUES (
    target_ip, NEW.room_id, target_nickname, moderation_reason,
    now() + interval '5 minutes'
  )
  ON CONFLICT (client_ip, room_id)
  DO UPDATE SET
    nickname = EXCLUDED.nickname,
    reason = EXCLUDED.reason,
    created_at = now(),
    expires_at = now() + interval '5 minutes';

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.wichat_award_public_message_point()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
  v_uid uuid;
  v_count integer;
  v_body text;
begin
  if coalesce(to_jsonb(new)->>'message_type','text') <> 'text' then
    return new;
  end if;
  v_body := btrim(coalesce(to_jsonb(new)->>'message', to_jsonb(new)->>'content',''));
  if char_length(v_body) < 3 then return new; end if;
  if coalesce(to_jsonb(new)->>'sender_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return new;
  end if;
  v_uid := (to_jsonb(new)->>'sender_id')::uuid;
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || ':daily-points', 0));
  select count(*) into v_count
  from public.chat_points_ledger
  where user_id = v_uid
    and reason = 'mensaje_publico'
    and created_at >= date_trunc('day', now());
  if v_count >= 20 then return new; end if;

  insert into public.chat_points_ledger(user_id,points_delta,reason,event_key)
  values (v_uid,1,'mensaje_publico','public-message:' || new.id::text)
  on conflict (event_key) do nothing;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.wichat_claim_account_session(p_device_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_current_device text;
  v_expires timestamptz;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Tenés que iniciar sesión.'; END IF;
  IF p_device_id IS NULL OR length(p_device_id) < 16 OR length(p_device_id) > 128 THEN
    RAISE EXCEPTION 'Identificador de dispositivo no válido.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_uid::text, 0));

  SELECT device_id, expires_at INTO v_current_device, v_expires
  FROM public.wichat_account_sessions WHERE user_id = v_uid;

  IF FOUND AND v_expires > now() AND v_current_device <> p_device_id THEN
    RETURN false;
  END IF;

  INSERT INTO public.wichat_account_sessions(user_id,device_id,expires_at,updated_at)
  VALUES(v_uid,p_device_id,now()+interval '2 minutes',now())
  ON CONFLICT(user_id) DO UPDATE
    SET device_id=EXCLUDED.device_id,
        expires_at=EXCLUDED.expires_at,
        updated_at=now();

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.wichat_contains_insult(txt text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare normalized text; custom_term text;
begin
 normalized:=public.wichat_normalize_moderation_text(txt);
 if normalized ~ '(^| )(pelotudo|pelotuda|boludo|boluda|boludeces|forro|forra|forros|puta|puto|putas|putos|mierda|mierdas|concha|hdp|pendejo|pendeja|gil|giles|idiota|idiotas|imbecil|estupido|estupida|tarado|tarada|cagada|cagado|cagon)( |$)' then
  return true;
 end if;
 for custom_term in select normalized_term from public.chat_moderation_terms where active and category in ('insulto','custom')
 loop
  if position(' '||custom_term||' ' in ' '||normalized||' ')>0 then return true; end if;
 end loop;
 return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.wichat_limit_user_reports()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare recent_count integer;
begin
 select count(*) into recent_count from public.chat_user_reports
 where reporter_id=new.reporter_id and created_at>now()-interval '24 hours';
 if recent_count>=5 then raise exception 'Alcanzaste el límite de 5 denuncias por día.'; end if;
 if exists(select 1 from public.chat_user_reports where reporter_id=new.reporter_id and target_user_id=new.target_user_id and created_at>now()-interval '1 hour') then
  raise exception 'Ya denunciaste a este usuario durante la última hora.';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.wichat_moderate_message()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
 total integer;
 active_ban boolean;
 clean_body text;
 spam_count integer;
 reason_text text;
begin
 if new.sender_id is null or new.room_id is null then return new; end if;
 select exists(select 1 from public.wichat_room_bans
   where sender_id=new.sender_id and room_id=new.room_id and expires_at>now())
 into active_ban;
 if active_ban then return null; end if;

 clean_body:=coalesce(new.message,new.content,'');
 if public.wichat_contains_insult(clean_body) then
  insert into public.wichat_insult_counts(sender_id,room_id,insult_count,updated_at)
  values(new.sender_id,new.room_id,1,now())
  on conflict(sender_id,room_id) do update
    set insult_count=public.wichat_insult_counts.insult_count+1,updated_at=now()
  returning insult_count into total;
  if total<3 then
   insert into public.wichat_moderation_events(sender_id,room_id,action,reason)
   values(new.sender_id,new.room_id,'warning_'||total,'Mensaje bloqueado por lenguaje no permitido');
   return null;
  end if;
  insert into public.wichat_room_bans(sender_id,room_id,nickname,reason,expires_at)
  values(new.sender_id,new.room_id,new.nickname,'Tres infracciones por lenguaje no permitido',now()+interval '5 minutes')
  on conflict(sender_id,room_id) do update set nickname=excluded.nickname,
    reason=excluded.reason,created_at=now(),expires_at=excluded.expires_at;
  insert into public.wichat_moderation_events(sender_id,room_id,action,reason,duration_minutes)
  values(new.sender_id,new.room_id,'ban','Tres infracciones por lenguaje no permitido',5);
  return null;
 end if;

 -- Spam repetitivo en la misma sala: tres repeticiones recientes generan advertencia/bloqueo.
 if coalesce(new.message_type,'text')='text' and length(trim(clean_body))>=4 then
  select count(*) into spam_count from public.messages
   where sender_id=new.sender_id and room_id=new.room_id
     and created_at>now()-interval '60 seconds'
     and public.wichat_normalize_moderation_text(message)=public.wichat_normalize_moderation_text(clean_body);
  if spam_count>=2 then
   insert into public.wichat_moderation_events(sender_id,room_id,action,reason)
   values(new.sender_id,new.room_id,'spam_blocked','Mensaje repetido bloqueado automáticamente');
   return null;
  end if;
 end if;
 return new;
end;
$function$

