CREATE OR REPLACE FUNCTION public.wichat_send_message(p_nickname text, p_message text, p_room_id bigint, p_sender_id text, p_admin_pin text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_nick text := btrim(coalesce(p_nickname,''));
  v_msg text := btrim(coalesce(p_message,''));
  v_admin boolean := false;
  v_count integer;
  v_bad boolean;
BEGIN
  IF auth.uid() IS NULL OR auth.uid()::text<>p_sender_id THEN
    RAISE EXCEPTION 'Sesión no válida.';
  END IF;

  IF length(v_nick)<1 OR length(v_nick)>25 THEN
    RAISE EXCEPTION 'Nick inválido.';
  END IF;

  IF length(v_msg)<1 OR length(v_msg)>1000 THEN
    RAISE EXCEPTION 'El mensaje debe tener entre 1 y 1000 caracteres.';
  END IF;

  IF NOT EXISTS(SELECT 1 FROM public.rooms WHERE id=p_room_id) THEN
    RAISE EXCEPTION 'La sala no existe.';
  END IF;

  v_admin := lower(v_nick)='unix'
    AND coalesce(public.verify_admin_pin(coalesce(p_admin_pin,'')),false);

  IF lower(v_nick)='unix' AND NOT v_admin THEN
    RAISE EXCEPTION 'El Nick UNIX está reservado.';
  END IF;

  IF NOT EXISTS(
    SELECT 1 FROM public.wichat_nicknames
    WHERE sender_id=p_sender_id
      AND nickname_norm=lower(v_nick)
      AND expires_at>now()
  ) THEN
    RAISE EXCEPTION 'La reserva de Nick venció. Volvé a ingresar.';
  END IF;

  IF NOT v_admin AND NOT public.check_chat_access(p_sender_id,p_room_id) THEN
    RAISE EXCEPTION 'No tenés acceso a esta sala en este momento.';
  END IF;

  v_bad := v_msg ~* '(^|[^[:alnum:]_])(puta|puto|mierda|mierdas|forro|pelotudo|pelotuda|conchudo|conchuda|concha|verga|pija|cag[oó]n|hdp|h[.]?d[.]?p[.]?|hijo de puta|hija de puta)([^[:alnum:]_]|$)';

  IF v_bad AND NOT v_admin THEN
    INSERT INTO public.wichat_badword_counts(sender_id,room_id,violation_count,updated_at)
    VALUES(p_sender_id,p_room_id,1,now())
    ON CONFLICT(sender_id,room_id) DO UPDATE
      SET violation_count=public.wichat_badword_counts.violation_count+1,
          updated_at=now()
    RETURNING violation_count INTO v_count;

    IF v_count<3 THEN
      INSERT INTO public.wichat_moderation_events(sender_id,room_id,action,created_at)
      VALUES(
        p_sender_id,
        p_room_id,
        CASE WHEN v_count=1 THEN 'warning_1' ELSE 'warning_2' END,
        now()
      );

      RETURN jsonb_build_object(
        'action',
        CASE WHEN v_count=1 THEN 'warning_1' ELSE 'warning_2' END,
        'count',v_count
      );
    END IF;

    INSERT INTO public.wichat_room_bans(
      sender_id,room_id,nickname,reason,created_at,expires_at
    )
    VALUES(
      p_sender_id,p_room_id,v_nick,
      'Tres infracciones por insultos',
      now(),now()+interval '5 minutes'
    )
    ON CONFLICT(sender_id,room_id) DO UPDATE
      SET nickname=EXCLUDED.nickname,
          reason=EXCLUDED.reason,
          created_at=now(),
          expires_at=now()+interval '5 minutes';

    INSERT INTO public.wichat_moderation_events(sender_id,room_id,action,created_at)
    VALUES(p_sender_id,p_room_id,'auto_kick',now());

    RETURN jsonb_build_object('action','auto_kick','count',v_count,'minutes',5);
  END IF;

  INSERT INTO public.messages(nickname,message,content,room_id,sender_id)
  VALUES(v_nick,v_msg,v_msg,p_room_id,p_sender_id);

  RETURN jsonb_build_object('action','sent');
END;
$function$
